// frontend/services/restaurantService.js
import axios from 'axios';

const API_BASE_URL = '/api/restaurants';

const restaurantService = {
  createRestaurant: async (restaurantData, token) => {
    try {
      const response = await axios.post(API_BASE_URL, restaurantData, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  getRestaurantByOwner: async (token) => {
    try {
      const response = await axios.get(`${API_BASE_URL}/owner`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  updateRestaurant: async (restaurantId, restaurantData, token) => {
    try {
      const response = await axios.put(`${API_BASE_URL}/${restaurantId}`, restaurantData, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  deleteRestaurant: async (restaurantId, token) => {
    try {
      const response = await axios.delete(`${API_BASE_URL}/${restaurantId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  getAllRestaurantsAdmin: async (token) => {
    try {
      const response = await axios.get(`${API_BASE_URL}/admin/all`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  verifyRestaurant: async (restaurantId, token) => {
    try {
      const response = await axios.patch(`${API_BASE_URL}/admin/${restaurantId}/verify`, {}, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },
};

export default restaurantService;
